package com.disasterrelief.controller;
import java.util.List; import com.disasterrelief.dto.ShelterRequest; import com.disasterrelief.model.Shelter; import com.disasterrelief.service.ReliefService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shelters") public class ShelterController { private final ReliefService s; public ShelterController(ReliefService s){this.s=s;} @GetMapping public List<Shelter> all(){return s.shelters();} @GetMapping("/{id}") public Shelter one(@PathVariable Long id){return s.shelter(id);} @PostMapping public ResponseEntity<Shelter> create(@Valid @RequestBody ShelterRequest x){return ResponseEntity.status(HttpStatus.CREATED).body(s.saveShelter(x,null));} @PutMapping("/{id}") public Shelter update(@PathVariable Long id,@Valid @RequestBody ShelterRequest x){return s.saveShelter(x,id);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){s.deleteShelter(id);} }
